-- Library catalogue: the approved worksheets, the cards that open the
-- exercises and features that already exist, and the future worksheets.
--
-- GENERATED from packages/shared-types/worksheets by emit-sql.ts.
-- Do not hand-edit: change the catalogue and regenerate, or the drift test
-- in packages/shared-types/__tests__/migration.test.ts will fail.

-- Therapist-only framing: the "For therapists:" line from the approved
-- document. Never serialized to a client.
ALTER TABLE "ToolRegistryEntry" ADD COLUMN "therapist_note" TEXT;

-- Step 1 constrained kind to exercise/worksheet and status to
-- draft/approved/retired. The Library needs one more of each: a `group`
-- card (Breathing opens four techniques) and `placeholder` (future
-- worksheets that exist only as a name).
ALTER TABLE "ToolRegistryEntry" DROP CONSTRAINT IF EXISTS "ToolRegistryEntry_kind_check";
ALTER TABLE "ToolRegistryEntry" ADD CONSTRAINT "ToolRegistryEntry_kind_check"
    CHECK ("kind" IN ('exercise', 'worksheet', 'group'));
ALTER TABLE "ToolRegistryEntry" DROP CONSTRAINT IF EXISTS "ToolRegistryEntry_status_check";
ALTER TABLE "ToolRegistryEntry" ADD CONSTRAINT "ToolRegistryEntry_status_check"
    CHECK ("status" IN ('draft', 'approved', 'retired', 'placeholder'));

-- Which Library card a row opens from. The four breathing techniques hang
-- off the one Breathing card; a row with NULL here is its own card.
ALTER TABLE "ToolRegistryEntry" ADD COLUMN "library_group" TEXT;

INSERT INTO "ToolRegistryEntry" ("id", "tool_id", "label", "label_hi", "text", "chat_guidable", "kind", "summary", "summary_hi", "section", "therapy_modality", "therapist_note", "access_mode", "load_level", "est_minutes", "content_en", "content_hi", "status", "approved_at", "sort_order", "library_group", "updated_at") VALUES
    ('c1b2a3d4-0000-4e00-9000-000000000001', 'mood_checkin', 'Mood check-in', 'Mood check-in', 'Check in with how you''re feeling and what set it off.', false, 'worksheet', 'Check in with how you''re feeling and what set it off.', 'Check in karo ki aap kaisa feel kar rahe ho, aur kis baat ne aisa kar diya.', 'notice_and_name', 'Mood monitoring (behavioural activation / CBT)', 'tracks mood, trigger and intensity over time; its intensity rating also drives the safety gate on demanding worksheets.', 'open', 'light', 1, $ws_mood_checkin${"version":1,"fields":[{"id":"trigger","type":"short_text","prompt":"What was happening just before you felt this?","helper":"A place, a person, a thought, a notification, nothing in particular. All of these count.","example":"Got my internal marks back."},{"id":"intensity","type":"scale_0_10","prompt":"How strong is this feeling right now?","minLabel":"0 = barely there","maxLabel":"10 = the strongest I've felt."}],"closing":{"text":"Noted. Noticing is a skill, and you just used it."}}$ws_mood_checkin$::jsonb, $ws_mood_checkin${"version":1,"fields":[{"id":"trigger","type":"short_text","prompt":"Aisa feel karne se thoda pehle kya ho raha tha?","helper":"Koi jagah, koi insaan, koi soch, koi notification, ya kuch bhi nahi. Sab count hota hai.","example":"Internal marks aa gaye the."},{"id":"intensity","type":"scale_0_10","prompt":"Abhi ye feeling kitni strong hai?","minLabel":"0 = bas thodi si","maxLabel":"10 = sabse zyada jo maine kabhi feel kiya."}],"closing":{"text":"Note kar liya. Notice karna ek skill hai, aur aapne abhi use kiya."}}$ws_mood_checkin$::jsonb, 'approved', '2026-11-09'::timestamp, 10, NULL, CURRENT_TIMESTAMP),
    ('c1b2a3d4-0000-4e00-9000-000000000002', 'ws_name_the_feeling', 'Name the feeling', 'Feeling ko naam do', 'Find a more exact word for what you''re feeling, and where you feel it.', false, 'worksheet', 'Find a more exact word for what you''re feeling, and where you feel it.', 'Jo aap feel kar rahe ho uske liye zyada sahi shabd dhoondo, aur kahan feel hota hai woh bhi.', 'notice_and_name', 'Emotion granularity, body awareness (DBT-informed)', 'emotion granularity and body awareness; useful early in therapy and before DBT skills.', 'open', 'light', 3, $ws_ws_name_the_feeling${"version":1,"intro":"Sometimes everything just feels like 'bad' or 'off.' Putting a more exact name on a feeling can make it a little easier to hold.","fields":[{"id":"feelings","type":"feelings_picker","prompt":"Pick the feeling closest to what's going on.","required":true,"maxSelections":3,"withStrength":true,"strengthPrompt":"How strong is each one?","feelings":[{"id":"sad","label":"sad"},{"id":"scared","label":"scared"},{"id":"angry","label":"angry"},{"id":"ashamed","label":"ashamed"},{"id":"happy","label":"happy"},{"id":"calm","label":"calm"},{"id":"numb","label":"numb"},{"id":"worried","label":"worried","parent":"scared"},{"id":"panicky","label":"panicky","parent":"scared"},{"id":"unsafe","label":"unsafe","parent":"scared"},{"id":"on_edge","label":"on edge","parent":"scared"}]},{"id":"body","type":"checklist","prompt":"Where do you notice it in your body?","helper":"There's no wrong answer. Some feelings don't show up in the body at all.","options":[{"value":"head","label":"head"},{"value":"jaw","label":"jaw"},{"value":"throat","label":"throat"},{"value":"chest","label":"chest"},{"value":"stomach","label":"stomach"},{"value":"shoulders","label":"shoulders"},{"value":"hands","label":"hands"},{"value":"legs","label":"legs"},{"value":"nowhere","label":"nowhere I can tell"}]},{"id":"one_sentence","type":"short_text","prompt":"If this feeling could say one sentence, what would it say?","example":"Don't mess this up."}],"closing":{"text":"You gave it a name. That's a step towards understanding it."}}$ws_ws_name_the_feeling$::jsonb, $ws_ws_name_the_feeling${"version":1,"intro":"Kabhi kabhi sab kuch bas 'bura' ya 'theek nahi' lagta hai. Feeling ko zyada sahi naam dene se use sambhalna thoda aasan ho sakta hai.","fields":[{"id":"feelings","type":"feelings_picker","prompt":"Jo abhi ho raha hai, uske sabse kareeb feeling chuno.","required":true,"maxSelections":3,"withStrength":true,"strengthPrompt":"Har ek kitni strong hai?","feelings":[{"id":"sad","label":"udaas"},{"id":"scared","label":"dara hua"},{"id":"angry","label":"gussa"},{"id":"ashamed","label":"sharminda"},{"id":"happy","label":"khush"},{"id":"calm","label":"shaant"},{"id":"numb","label":"sunn"},{"id":"worried","label":"pareshan","parent":"scared"},{"id":"panicky","label":"ghabrahat","parent":"scared"},{"id":"unsafe","label":"unsafe lag raha","parent":"scared"},{"id":"on_edge","label":"chidchida / edge par","parent":"scared"}]},{"id":"body","type":"checklist","prompt":"Body mein kahan mehsoos hota hai?","helper":"Koi galat jawab nahi hai. Kuch feelings body mein dikhti hi nahi.","options":[{"value":"head","label":"sar"},{"value":"jaw","label":"jabda"},{"value":"throat","label":"gala"},{"value":"chest","label":"seene"},{"value":"stomach","label":"pet"},{"value":"shoulders","label":"kandhe"},{"value":"hands","label":"haath"},{"value":"legs","label":"pair"},{"value":"nowhere","label":"kuch bhi mehsoos nahi hota"}]},{"id":"one_sentence","type":"short_text","prompt":"Agar ye feeling ek line bol sakti, toh kya kehti?","example":"Ise bigaadna mat."}],"closing":{"text":"Aapne ise naam de diya. Samajhne ki taraf ye ek kadam hai."}}$ws_ws_name_the_feeling$::jsonb, 'approved', '2026-11-09'::timestamp, 20, NULL, CURRENT_TIMESTAMP),
    ('c1b2a3d4-0000-4e00-9000-000000000003', 'grounding_5431', '5-4-3-2-1 grounding', '5-4-3-2-1 grounding', '5-4-3-2-1 grounding — notice five things you can see, four you can touch, three you can hear, two you can smell, one you can taste.', false, 'exercise', '5-4-3-2-1 grounding — notice five things you can see, four you can touch, three you can hear, two you can smell, one you can taste.', 'Paanch cheezein dekho, chaar chizo ko chuo, teen cheezein suno, do cheezein sungo, ek cheez ka swaad lo.', 'calm_my_body', 'Sensory grounding (for high arousal, dissociation, panic)', 'grounding through the senses for high distress, dissociation or panic.', 'open', 'light', 3, $ws_grounding_5431${"version":1,"fields":[{"id":"feeling_after","type":"scale_0_10","prompt":"How are you feeling now?"}],"closing":{"text":"You're here. Take whatever time you need before moving on.","buttons":[{"label":"Open my Treasure Box","action":"treasure_box"},{"label":"Done for now","action":"done"}]}}$ws_grounding_5431$::jsonb, $ws_grounding_5431${"version":1,"fields":[{"id":"feeling_after","type":"scale_0_10","prompt":"Ab kaisa lag raha hai?"}],"closing":{"text":"Aap yahan ho. Aage badhne se pehle jitna time chahiye le lo.","buttons":[{"label":"Mera Treasure Box kholo","action":"treasure_box"},{"label":"Abhi ke liye bas","action":"done"}]}}$ws_grounding_5431$::jsonb, 'approved', '2026-11-09'::timestamp, 10, NULL, CURRENT_TIMESTAMP),
    ('c1b2a3d4-0000-4e00-9000-000000000004', 'breathing', 'Breathing', 'Breathing', 'Slow your breathing with four short exercises.', false, 'group', 'Slow your breathing with four short exercises.', 'Chaar chhoti exercises se apni breathing dheemi karo.', 'calm_my_body', 'Paced breathing', 'four paced-breathing techniques; each keeps its own clinically reviewed description.', 'open', 'light', 3, $ws_breathing${"version":1,"fields":[{"id":"feeling_after","type":"scale_0_10","prompt":"How are you feeling now?"}]}$ws_breathing$::jsonb, $ws_breathing${"version":1,"fields":[{"id":"feeling_after","type":"scale_0_10","prompt":"Ab kaisa lag raha hai?"}]}$ws_breathing$::jsonb, 'approved', '2026-11-09'::timestamp, 20, NULL, CURRENT_TIMESTAMP),
    ('c1b2a3d4-0000-4e00-9000-000000000005', 'ws_thought_record', 'Thought record', 'Thought record', 'Slow down one thought and look at it from a few sides.', false, 'worksheet', 'Slow down one thought and look at it from a few sides.', 'Ek soch ko dheema karo aur use kai taraf se dekho.', 'untangle_thoughts', 'CBT thought record', 'classic CBT thought record. The other way of seeing it is written by the client only; OKUVU never suggests one.', 'assigned', 'demanding', 10, $ws_ws_thought_record${"version":1,"intro":"Thoughts can feel like facts, especially when they show up fast. This is a way to slow one down and look at it from a few sides. Pick one moment from today or this week.","fields":[{"id":"what_happened","type":"short_text","prompt":"What happened?","required":true,"helper":"Just the facts, like a camera would see it: where, when, who.","example":"My friend saw my message and didn't reply for five hours."},{"id":"feelings","type":"feelings_picker","prompt":"What did you feel, and how strongly?","required":true,"maxSelections":3,"withStrength":true,"strengthPrompt":"How strong is each one?","feelings":[{"id":"sad","label":"sad"},{"id":"scared","label":"scared"},{"id":"angry","label":"angry"},{"id":"ashamed","label":"ashamed"},{"id":"happy","label":"happy"},{"id":"calm","label":"calm"},{"id":"numb","label":"numb"},{"id":"worried","label":"worried","parent":"scared"},{"id":"panicky","label":"panicky","parent":"scared"},{"id":"unsafe","label":"unsafe","parent":"scared"},{"id":"on_edge","label":"on edge","parent":"scared"}]},{"id":"thought","type":"long_text","prompt":"What went through your mind?","required":true,"helper":"Write the thought the way it sounded in your head, even if it seems extreme.","example":"She's annoyed with me. I always say the wrong thing."},{"id":"strongest_thought","type":"short_text","prompt":"Which thought feels the strongest?","required":true},{"id":"belief_before","type":"scale_0_100","prompt":"How much do you believe it right now?","required":true},{"id":"evidence_for","type":"row_list","prompt":"What makes this thought feel true?","helper":"Things that actually happened, not guesses.","columns":[{"id":"item","label":"What makes it feel true","type":"text"}]},{"id":"evidence_against","type":"row_list","prompt":"What doesn't quite fit with this thought?","helper":"Anything that suggests it might not be the whole story. If you can't find anything yet, that's okay. Leave it and come back.","columns":[{"id":"item","label":"What doesn't quite fit","type":"text"}]},{"id":"another_view","type":"long_text","prompt":"Looking at both lists, is there another way to see this?","helper":"This doesn't have to be positive. It just has to be fair to all of what you wrote."},{"id":"belief_after","type":"scale_0_100","prompt":"Now, how much do you believe the original thought?"},{"id":"feeling_after","type":"scale_0_10","prompt":"And how strong is the feeling now?"}],"closing":{"text":"Whatever you found, you looked at your own mind with care. That's the practice.","buttons":[{"label":"Save to my Treasure Box","action":"treasure_box"},{"label":"Done","action":"done"}]}}$ws_ws_thought_record$::jsonb, $ws_ws_thought_record${"version":1,"intro":"Soch kabhi sach jaisi lagti hai, khaas kar jab woh tezi se aati hai. Ye tareeka ek soch ko dheema karke use kai taraf se dekhne ka hai. Aaj ya is hafte ka ek pal chuno.","fields":[{"id":"what_happened","type":"short_text","prompt":"Kya hua tha?","required":true,"helper":"Bas facts, jaise camera dekhta hai: kahan, kab, kaun.","example":"Mere dost ne message dekha aur paanch ghante reply nahi kiya."},{"id":"feelings","type":"feelings_picker","prompt":"Aapko kya feel hua, aur kitna strong?","required":true,"maxSelections":3,"withStrength":true,"strengthPrompt":"Har ek kitni strong hai?","feelings":[{"id":"sad","label":"udaas"},{"id":"scared","label":"dara hua"},{"id":"angry","label":"gussa"},{"id":"ashamed","label":"sharminda"},{"id":"happy","label":"khush"},{"id":"calm","label":"shaant"},{"id":"numb","label":"sunn"},{"id":"worried","label":"pareshan","parent":"scared"},{"id":"panicky","label":"ghabrahat","parent":"scared"},{"id":"unsafe","label":"unsafe lag raha","parent":"scared"},{"id":"on_edge","label":"chidchida / edge par","parent":"scared"}]},{"id":"thought","type":"long_text","prompt":"Dimaag mein kya chala?","required":true,"helper":"Soch ko waise likho jaise dimaag mein suni thi, chahe woh extreme lage.","example":"Woh mujhse chidh gayi hai. Main hamesha galat bolta hoon."},{"id":"strongest_thought","type":"short_text","prompt":"Kaunsi soch sabse strong lagti hai?","required":true},{"id":"belief_before","type":"scale_0_100","prompt":"Abhi aap ise kitna sach maante ho?","required":true},{"id":"evidence_for","type":"row_list","prompt":"Kya cheez is soch ko sach jaisa banati hai?","helper":"Woh cheezein jo sach mein hui, andaze nahi.","columns":[{"id":"item","label":"Ise sach jaisa kya banata hai","type":"text"}]},{"id":"evidence_against","type":"row_list","prompt":"Kya cheez is soch se poori tarah match nahi karti?","helper":"Kuch bhi jo bataye ki ye poori kahani nahi ho sakti. Agar abhi kuch na mile, koi baat nahi. Chhod do aur baad mein aao.","columns":[{"id":"item","label":"Jo poori tarah match nahi karta","type":"text"}]},{"id":"another_view","type":"long_text","prompt":"Dono list dekhkar, kya ise dekhne ka koi aur tareeka hai?","helper":"Ise positive hona zaroori nahi. Bas jo aapne likha, uske saath insaaf karna hai."},{"id":"belief_after","type":"scale_0_100","prompt":"Ab original soch ko kitna sach maante ho?"},{"id":"feeling_after","type":"scale_0_10","prompt":"Aur ab feeling kitni strong hai?"}],"closing":{"text":"Jo bhi mila, aapne apne dimaag ko pyaar se dekha. Yahi practice hai.","buttons":[{"label":"Mere Treasure Box mein save karo","action":"treasure_box"},{"label":"Ho gaya","action":"done"}]}}$ws_ws_thought_record$::jsonb, 'approved', '2026-11-09'::timestamp, 10, NULL, CURRENT_TIMESTAMP),
    ('c1b2a3d4-0000-4e00-9000-000000000006', 'ws_thinking_trap', 'Spot the thinking trap', 'Thinking trap pehchano', 'Notice when a thought is taking a mental shortcut.', false, 'worksheet', 'Notice when a thought is taking a mental shortcut.', 'Dhyan do jab koi soch dimaag ka shortcut le rahi ho.', 'untangle_thoughts', 'CBT cognitive distortions', 'names common thinking errors in plain language. Use after explaining thinking errors in session.', 'assigned', 'demanding', 5, $ws_ws_thinking_trap${"version":1,"intro":"Our minds have shortcuts. They're quick, but sometimes they take us somewhere unfair. See if any of these sound familiar.","fields":[{"id":"thought","type":"short_text","prompt":"Write down a thought that's been bothering you.","required":true},{"id":"patterns","type":"checklist","prompt":"Does it fit any of these patterns?","required":true,"options":[{"value":"mind_reading","label":"Mind reading","description":"guessing what others think without checking."},{"value":"fortune_telling","label":"Fortune telling","description":"being sure something will go badly."},{"value":"all_or_nothing","label":"All-or-nothing","description":"if it's not perfect, it's a failure."},{"value":"catastrophising","label":"Catastrophising","description":"jumping to the worst possible outcome."},{"value":"should_statements","label":"Should statements","description":"strict rules about how I or others must be."},{"value":"labelling","label":"Labelling","description":"calling myself a name instead of describing what happened."},{"value":"discounting_the_good","label":"Discounting the good","description":"deciding positives don't count."},{"value":"emotional_reasoning","label":"Emotional reasoning","description":"I feel it, so it must be true."},{"value":"none","label":"None of these fit."}]},{"id":"noticing","type":"long_text","prompt":"What do you notice now that you've named it?"}],"closing":{"text":"Spotting a pattern doesn't make the feeling wrong. It just gives you a little more room."}}$ws_ws_thinking_trap$::jsonb, $ws_ws_thinking_trap${"version":1,"intro":"Dimaag ke paas shortcuts hote hain. Woh tez hote hain, par kabhi kabhi galat jagah le jaate hain. Dekho kya inme se kuch jaana-pehchana lagta hai.","fields":[{"id":"thought","prompt":"Ek soch likho jo pareshan kar rahi hai.","type":"short_text","required":true},{"id":"patterns","type":"checklist","prompt":"Kya ye in patterns mein se kisi se match karti hai?","required":true,"options":[{"value":"mind_reading","label":"Mind reading","description":"bina poochhe maan lena ki doosre kya soch rahe hain."},{"value":"fortune_telling","label":"Fortune telling","description":"pakka maan lena ki kuch bura hi hoga."},{"value":"all_or_nothing","label":"All-or-nothing","description":"perfect nahi toh fail."},{"value":"catastrophising","label":"Catastrophising","description":"seedha sabse bura anjaam soch lena."},{"value":"should_statements","label":"Should statements","description":"sakht niyam ki mujhe ya doosron ko aisa hi hona chahiye."},{"value":"labelling","label":"Labelling","description":"kya hua ye batane ke bajaye khud ko ek naam de dena."},{"value":"discounting_the_good","label":"Discounting the good","description":"achhi cheezein ginne layak nahi maanna."},{"value":"emotional_reasoning","label":"Emotional reasoning","description":"mujhe aisa lagta hai, isliye sach hoga."},{"value":"none","label":"Inme se kuch bhi match nahi karta."}]},{"id":"noticing","type":"long_text","prompt":"Naam dene ke baad ab kya notice karte ho?"}],"closing":{"text":"Pattern pehchanne se feeling galat nahi ho jaati. Bas thodi si jagah ban jaati hai."}}$ws_ws_thinking_trap$::jsonb, 'approved', '2026-11-09'::timestamp, 20, NULL, CURRENT_TIMESTAMP),
    ('c1b2a3d4-0000-4e00-9000-000000000007', 'ws_worry_tree', 'Worry tree', 'Worry tree', 'Sort the worries you can act on from the ones that just keep circling.', false, 'worksheet', 'Sort the worries you can act on from the ones that just keep circling.', 'Jo worries aap solve kar sakte ho unhe unse alag karo jo bas ghoomti rehti hain.', 'untangle_thoughts', 'CBT worry postponement', 'separates worries that need action from "what if" worries, then contains the rest with a set worry time.', 'assigned', 'demanding', 5, $ws_ws_worry_tree${"version":1,"intro":"Some worries need action. Others just keep circling. This helps you sort which is which.","fields":[{"id":"worry","type":"short_text","prompt":"What's the worry?","required":true,"example":"What if I don't get placed this year?"},{"id":"when","type":"choice","prompt":"Is this about something happening now, or a 'what if' about later?","required":true,"options":[{"value":"now","label":"Something happening now"},{"value":"what_if","label":"A 'what if'"}]},{"id":"can_act","type":"choice","prompt":"Is there anything you can do about it?","required":true,"options":[{"value":"yes","label":"Yes"},{"value":"not_now","label":"Not right now"}]},{"id":"small_step","type":"short_text","prompt":"What's one small step, and when could you do it?","visibleWhen":{"field":"can_act","in":["yes"]}},{"id":"step_when","type":"datetime","prompt":"When could you do it?","withDate":true,"withTime":true,"visibleWhen":{"field":"can_act","in":["yes"]}},{"id":"worry_slot","type":"datetime","prompt":"Park it for worry time.","helper":"When the worry shows up before then, remind yourself: 'I've got a time for this.' Then bring your attention back to what you're doing.","withDate":true,"withTime":true,"visibleWhen":{"field":"can_act","in":["not_now"]}},{"id":"worry_time_review","type":"long_text","prompt":"Look back at what you parked. Does it still feel as urgent? Is there anything you can do about it now?","visibleWhen":{"field":"can_act","in":["not_now"]}}],"closing":{"text":"You don't have to solve everything at once."}}$ws_ws_worry_tree$::jsonb, $ws_ws_worry_tree${"version":1,"intro":"Kuch worries ke liye kuch karna padta hai. Kuch bas ghoomti rehti hain. Ye unhe alag karne mein madad karta hai.","fields":[{"id":"worry","type":"short_text","prompt":"Worry kya hai?","required":true,"example":"Agar is saal placement nahi mili toh?"},{"id":"when","type":"choice","prompt":"Ye ab ho rahi kisi cheez ke baare mein hai, ya aage ke \"kya hoga\" ke baare mein?","required":true,"options":[{"value":"now","label":"Ab ho rahi koi cheez"},{"value":"what_if","label":"Aage ka \"kya hoga\""}]},{"id":"can_act","type":"choice","prompt":"Kya aap iske baare mein kuch kar sakte ho?","required":true,"options":[{"value":"yes","label":"Haan"},{"value":"not_now","label":"Abhi nahi"}]},{"id":"small_step","type":"short_text","prompt":"Ek chhota kadam kya ho sakta hai, aur kab kar sakte ho?","visibleWhen":{"field":"can_act","in":["yes"]}},{"id":"step_when","type":"datetime","prompt":"Kab kar sakte ho?","withDate":true,"withTime":true,"visibleWhen":{"field":"can_act","in":["yes"]}},{"id":"worry_slot","type":"datetime","prompt":"Ise worry time ke liye park kar do.","helper":"Jab us time se pehle worry aaye, khud ko yaad dilao: 'Iske liye mere paas time hai.' Phir apna dhyan wapas us kaam par lao jo kar rahe ho.","withDate":true,"withTime":true,"visibleWhen":{"field":"can_act","in":["not_now"]}},{"id":"worry_time_review","type":"long_text","prompt":"Jo park kiya tha use dobara dekho. Kya ab bhi utna urgent lagta hai? Ab iske baare mein kuch kar sakte ho?","visibleWhen":{"field":"can_act","in":["not_now"]}}],"closing":{"text":"Sab kuch ek saath solve karna zaroori nahi."}}$ws_ws_worry_tree$::jsonb, 'approved', '2026-11-09'::timestamp, 30, NULL, CURRENT_TIMESTAMP),
    ('c1b2a3d4-0000-4e00-9000-000000000008', 'ws_small_things', 'Small things planner', 'Chhoti cheezein planner', 'Plan a few small things for the coming days. Tiny is fine.', false, 'worksheet', 'Plan a few small things for the coming days. Tiny is fine.', 'Aane wale dino ke liye kuch chhoti cheezein plan karo. Chhoti bhi theek hai.', 'do_what_matters', 'Behavioural activation', 'behavioural activation with achievement and enjoyment ratings. Light so it stays open on low-mood days, when it matters most.', 'assigned', 'light', 5, $ws_ws_small_things${"version":1,"intro":"When you're low, waiting to feel like doing something can take forever. Sometimes doing a small thing comes first, and the feeling follows a little. Plan a few small things. Tiny is fine.","fields":[{"id":"plan","type":"row_list","prompt":"Plan up to three small things for the next few days.","helper":"Mix it up if you can: one thing you enjoy, one thing that gets something done, one thing that connects you with someone.","example":"Walk to the chai stall · Reply to one pending email · Send a meme to my cousin.","maxRows":3,"columns":[{"id":"what","label":"What","type":"text"},{"id":"when","label":"When","type":"datetime"}]},{"id":"did_it","type":"choice","prompt":"Did you do it?","options":[{"value":"yes","label":"Yes"},{"value":"partly","label":"Partly"},{"value":"no","label":"Not this time"}]},{"id":"achievement","type":"scale_0_10","prompt":"How much did it feel like an achievement?","visibleWhen":{"field":"did_it","in":["yes","partly"]}},{"id":"enjoyment","type":"scale_0_10","prompt":"How much did you enjoy it?","visibleWhen":{"field":"did_it","in":["yes","partly"]}},{"id":"what_got_in_the_way","type":"short_text","prompt":"What got in the way?","helper":"No judgement. This helps you and your therapist plan better.","visibleWhen":{"field":"did_it","in":["no"]}}],"closing":{"text":"Every small thing counts, including the ones that didn't happen. You're learning what works for you."}}$ws_ws_small_things$::jsonb, $ws_ws_small_things${"version":1,"intro":"Jab mood low hota hai, \"man kare tab karunga\" ka intezaar bahut lamba ho jaata hai. Kabhi kabhi chhota kaam pehle karna padta hai, aur feeling thodi si peeche aati hai. Kuch chhote kaam plan karo. Bahut chhote bhi chalenge.","fields":[{"id":"plan","type":"row_list","prompt":"Aane wale kuch dino ke liye teen tak chhote kaam plan karo.","helper":"Ho sake toh mix karo: ek cheez jo aapko pasand hai, ek jo kaam nikal de, ek jo kisi se judne mein madad kare.","example":"Chai ki thela tak paidal jana · Ek pending email ka jawab · Cousin ko meme bhejna.","maxRows":3,"columns":[{"id":"what","label":"Kya","type":"text"},{"id":"when","label":"Kab","type":"datetime"}]},{"id":"did_it","type":"choice","prompt":"Kya aapne kiya?","options":[{"value":"yes","label":"Haan"},{"value":"partly","label":"Thoda sa"},{"value":"no","label":"Is baar nahi"}]},{"id":"achievement","type":"scale_0_10","prompt":"Kitna achievement jaisa laga?","visibleWhen":{"field":"did_it","in":["yes","partly"]}},{"id":"enjoyment","type":"scale_0_10","prompt":"Kitna maza aaya?","visibleWhen":{"field":"did_it","in":["yes","partly"]}},{"id":"what_got_in_the_way","type":"short_text","prompt":"Beech mein kya aaya?","helper":"Koi judgement nahi. Isse aapko aur aapke therapist ko behtar plan banane mein madad milti hai.","visibleWhen":{"field":"did_it","in":["no"]}}],"closing":{"text":"Har chhoti cheez count hoti hai, woh bhi jo nahi hui. Aap seekh rahe ho ki aapke liye kya kaam karta hai."}}$ws_ws_small_things$::jsonb, 'approved', '2026-11-09'::timestamp, 10, NULL, CURRENT_TIMESTAMP),
    ('c1b2a3d4-0000-4e00-9000-000000000009', 'ws_values_compass', 'Values compass', 'Values compass', 'Notice what matters to you, and take one small step towards it.', false, 'worksheet', 'Notice what matters to you, and take one small step towards it.', 'Dekho aapke liye kya maayne rakhta hai, aur us taraf ek chhota kadam lo.', 'do_what_matters', 'ACT values work', 'ACT values work across life areas, ending in one small committed step.', 'assigned', 'light', 10, $ws_ws_values_compass${"version":1,"intro":"Goals are things you finish. Values are directions you keep walking in, like being a caring friend or someone who keeps learning. This helps you notice what matters to you.","fields":[{"id":"areas","type":"checklist","prompt":"Which areas of life matter most to you right now?","required":true,"maxSelections":3,"options":[{"value":"family","label":"family"},{"value":"friendships","label":"friendships"},{"value":"love","label":"love and relationships"},{"value":"studies_work","label":"studies or work"},{"value":"health","label":"health and body"},{"value":"fun_rest","label":"fun and rest"},{"value":"community","label":"community and giving back"},{"value":"growth","label":"growth and learning"},{"value":"faith","label":"faith or spirituality"}]},{"id":"who_there","type":"row_list","prompt":"For each area: what kind of person do you want to be there?","helper":"Describe how you want to act, not what you want to get.","example":"For friendships: \"Someone who shows up, even when it’s inconvenient.\"","maxRows":3,"columns":[{"id":"area","label":"Area","type":"text"},{"id":"person","label":"What kind of person","type":"text"}]},{"id":"how_close","type":"row_list","prompt":"How close are you living to that right now?","helper":"This isn't a score of how good you are. It just shows where you'd like to move.","maxRows":3,"columns":[{"id":"area","label":"Area","type":"text"},{"id":"closeness","label":"How close","type":"scale_0_10"}]},{"id":"one_step","type":"short_text","prompt":"Pick one area. What's one small thing you could do this week that points in that direction?"},{"id":"step_date","type":"datetime","prompt":"When could you do it?","withDate":true}],"closing":{"text":"You don't need to feel ready to take a step in a direction you care about.","buttons":[{"label":"Save to my Treasure Box","action":"treasure_box"},{"label":"Done","action":"done"}]}}$ws_ws_values_compass$::jsonb, $ws_ws_values_compass${"version":1,"intro":"Goals woh cheezein hain jo poori ho jaati hain. Values woh disha hain jinme aap chalte rehte ho, jaise ek samajhdaar dost hona ya seekhte rehna. Ye aapko dekhne mein madad karta hai ki aapke liye kya maayne rakhta hai.","fields":[{"id":"areas","type":"checklist","prompt":"Abhi zindagi ke kaunse hisse aapke liye sabse zyada maayne rakhte hain?","required":true,"maxSelections":3,"options":[{"value":"family","label":"parivaar"},{"value":"friendships","label":"dost"},{"value":"love","label":"pyaar aur rishtey"},{"value":"studies_work","label":"padhai ya kaam"},{"value":"health","label":"sehat aur body"},{"value":"fun_rest","label":"masti aur aaram"},{"value":"community","label":"samaaj aur doosron ki madad"},{"value":"growth","label":"seekhna aur aage badhna"},{"value":"faith","label":"vishwas ya aadhyatm"}]},{"id":"who_there","type":"row_list","prompt":"Har hisse ke liye: wahan aap kaise insaan banna chahte ho?","helper":"Bataye ki aap kaise pesh aana chahte ho, ye nahi ki kya paana chahte ho.","example":"Dosti ke liye: \"Woh insaan jo mushkil ho tab bhi saath khada ho.\"","maxRows":3,"columns":[{"id":"area","label":"Hissa","type":"text"},{"id":"person","label":"Kaise insaan","type":"text"}]},{"id":"how_close","type":"row_list","prompt":"Abhi aap us hisse mein kitna karib jee rahe ho?","helper":"Ye aapke achhe hone ka score nahi hai. Bas batata hai ki aap kahan jaana chahte ho.","maxRows":3,"columns":[{"id":"area","label":"Hissa","type":"text"},{"id":"closeness","label":"Kitna karib","type":"scale_0_10"}]},{"id":"one_step","type":"short_text","prompt":"Ek hissa chuno. Is hafte ek chhoti cheez kya ho sakti hai jo us disha mein le jaaye?"},{"id":"step_date","type":"datetime","prompt":"Kab kar sakte ho?","withDate":true}],"closing":{"text":"Jis disha ki aapko parwah hai, us taraf kadam ke liye taiyaar mehsoos karna zaroori nahi.","buttons":[{"label":"Mere Treasure Box mein save karo","action":"treasure_box"},{"label":"Ho gaya","action":"done"}]}}$ws_ws_values_compass$::jsonb, 'approved', '2026-11-09'::timestamp, 20, NULL, CURRENT_TIMESTAMP),
    ('c1b2a3d4-0000-4e00-9000-00000000000a', 'ws_hard_conversation', 'Plan a hard conversation', 'Mushkil conversation plan karo', 'Plan what you want to say before a difficult conversation.', false, 'worksheet', 'Plan what you want to say before a difficult conversation.', 'Mushkil baat se pehle plan karo ki aap kya kehna chahte ho.', 'people_boundaries', 'DBT interpersonal effectiveness (DEAR MAN)', 'DBT interpersonal effectiveness (DEAR MAN structure), in plain language. The skill name appears only in a small "Based on" line, so it stays approachable.', 'assigned', 'light', 10, $ws_ws_hard_conversation${"version":1,"intro":"Asking for something, or saying no, is hard, especially with family or people you care about. Planning what you want to say can make it feel less overwhelming. You choose whether and when to use it.","fields":[{"id":"who_what","type":"short_text","prompt":"Who is this conversation with, and what's it about?","required":true,"example":"My dad, about taking a gap semester."},{"id":"outcome","type":"short_text","prompt":"What do you want to come out of it?","required":true,"helper":"Be as clear as you can, for example 'I want them to hear my reasons' or 'I want to say no to the trip.'"},{"id":"describe","type":"short_text","prompt":"Describe: What's the situation, just the facts?","required":true},{"id":"express","type":"short_text","prompt":"Express: How do you feel about it? Try starting with 'I feel…'","required":true},{"id":"ask","type":"short_text","prompt":"Ask: What exactly are you asking for, or saying no to?","required":true},{"id":"reinforce","type":"short_text","prompt":"Reinforce: Why might this be good for them too, or for your relationship?"},{"id":"stay_on_track","type":"short_text","prompt":"Stay on track: If the conversation drifts or gets heated, what's one line you can come back to?","example":"I hear you. I'd still like us to think about this."},{"id":"stay_steady","type":"checklist","prompt":"Stay steady: How do you want to sound: calm, firm, kind?","options":[{"value":"calm","label":"calm"},{"value":"firm","label":"firm"},{"value":"kind","label":"kind"}]},{"id":"be_open","type":"short_text","prompt":"Be open: What could you accept if you can't get everything you want?"},{"id":"summary","type":"instruction","prompt":"Here's your plan.","showAnswers":true}],"closing":{"text":"You don't control how they respond. You can control how clearly you show up.","buttons":[{"label":"Save to my Treasure Box","action":"treasure_box"},{"label":"Done","action":"done"}]}}$ws_ws_hard_conversation$::jsonb, $ws_ws_hard_conversation${"version":1,"intro":"Kuch maangna, ya na kehna, mushkil hota hai — khaas kar ghar walon ya apne logon ke saath. Pehle se soch lena ki kya kehna hai, ise thoda aasan bana deta hai. Use karna hai ya nahi, kab karna hai, ye aap decide karte ho.","fields":[{"id":"who_what","type":"short_text","prompt":"Ye baat kisse karni hai, aur kis baare mein?","required":true,"example":"Papa se, gap semester lene ke baare mein."},{"id":"outcome","type":"short_text","prompt":"Aap chahte ho iska natija kya ho?","required":true,"helper":"Jitna saaf keh sako kaho, jaise 'Main chahta hoon woh mere reasons sunein' ya 'Main trip ke liye na kehna chahta hoon.'"},{"id":"describe","type":"short_text","prompt":"Describe: Situation kya hai, sirf facts?","required":true},{"id":"express","type":"short_text","prompt":"Express: Aapko is baare mein kaisa lagta hai? 'I feel…' se shuru karke dekho","required":true},{"id":"ask","type":"short_text","prompt":"Ask: Aap exactly kya maang rahe ho, ya kis baat ko na keh rahe ho?","required":true},{"id":"reinforce","type":"short_text","prompt":"Reinforce: Ye unke liye bhi achha kyun ho sakta hai, ya rishte ke liye?"},{"id":"stay_on_track","type":"short_text","prompt":"Stay on track: Baat bhatak jaaye ya garam ho jaaye, toh wapas aane ke liye aapki ek line kya hogi?","example":"Main sun raha hoon. Phir bhi chahta hoon ki hum is baare mein sochein."},{"id":"stay_steady","type":"checklist","prompt":"Stay steady: Aap kaisa sunai dena chahte ho: shaant, pakka, ya narm?","options":[{"value":"calm","label":"shaant"},{"value":"firm","label":"pakka"},{"value":"kind","label":"narm"}]},{"id":"be_open","type":"short_text","prompt":"Be open: Poora nahi mila toh aap kya accept kar sakte ho?"},{"id":"summary","type":"instruction","prompt":"Ye aapka plan hai.","showAnswers":true}],"closing":{"text":"Unka jawab aapke haath mein nahi hai. Aapke haath mein ye hai ki aap kitni saaf tarah se pesh aate ho.","buttons":[{"label":"Mere Treasure Box mein save karo","action":"treasure_box"},{"label":"Ho gaya","action":"done"}]}}$ws_ws_hard_conversation$::jsonb, 'approved', '2026-11-09'::timestamp, 10, NULL, CURRENT_TIMESTAMP),
    ('c1b2a3d4-0000-4e00-9000-00000000000b', 'ws_kind_friend_letter', 'A letter from a kind friend', 'Ek pyaar karne wale dost ka khat', 'Write to yourself the way a caring friend would.', false, 'worksheet', 'Write to yourself the way a caring friend would.', 'Khud ko waise likho jaise ek samajhdaar dost likhta.', 'be_kinder', 'Compassion-focused therapy (letter writing)', 'compassion-focused letter writing. Marked demanding because it can stir up strong shame or grief, so it is better done when the client is steadier.', 'assigned', 'demanding', 10, $ws_ws_kind_friend_letter${"version":1,"intro":"Most of us talk to ourselves in ways we'd never talk to a friend. This is a chance to try a different voice.","fields":[{"id":"hard_on_yourself","type":"long_text","prompt":"What's something you've been hard on yourself about lately?","required":true,"helper":"Write it the way your inner critic says it."},{"id":"who","type":"short_text","prompt":"Picture someone who cares about you without conditions. It can be a real person, someone you've imagined, or a wiser, kinder version of you. Who are you picturing?"},{"id":"letter","type":"long_text","prompt":"Write to yourself as they would.","required":true,"helper":"What would they understand about why this is hard?, What would they want you to know?, What would they hope for you?"},{"id":"reading_it","type":"short_text","prompt":"Read your letter back. How does it feel to read it?","helper":"If it feels awkward or untrue, that's very common. Kindness towards yourself can take practice."}],"closing":{"text":"You can come back to this letter whenever you need it.","buttons":[{"label":"Save to my Treasure Box","action":"treasure_box"},{"label":"Done","action":"done"}]}}$ws_ws_kind_friend_letter$::jsonb, $ws_ws_kind_friend_letter${"version":1,"intro":"Hum sab apne aap se waise baat nahi karte jaise dost se karte hain. Ye ek alag awaaz aazmane ka mauka hai.","fields":[{"id":"hard_on_yourself","type":"long_text","prompt":"Haal hi mein aap kis baat par khud ko kaafi kathor rahe ho?","required":true,"helper":"Ise waise likho jaise aapka andar ka critic kehta hai."},{"id":"who","type":"short_text","prompt":"Kisi aise insaan ko yaad karo jo bina shart aapki parwah karta hai. Woh koi asli insaan ho sakta hai, koi jo aapne socha ho, ya aapka khud ka ek zyada samajhdaar, narm version. Aap kisko yaad kar rahe ho?"},{"id":"letter","type":"long_text","prompt":"Khud ko waise likho jaise woh likhte.","required":true,"helper":"Woh kya samajhte honge ki ye mushkil kyun hai? Woh aapko kya batana chahte honge? Woh aapke liye kya ummeed rakhte honge?"},{"id":"reading_it","type":"short_text","prompt":"Apna khat dobara padho. Padhkar kaisa lagta hai?","helper":"Agar ajeeb ya jhoota lage, toh ye bahut aam hai. Khud par narmi practice se aati hai."}],"closing":{"text":"Jab zaroorat ho, aap is khat par wapas aa sakte ho.","buttons":[{"label":"Mere Treasure Box mein save karo","action":"treasure_box"},{"label":"Ho gaya","action":"done"}]}}$ws_ws_kind_friend_letter$::jsonb, 'approved', '2026-11-09'::timestamp, 10, NULL, CURRENT_TIMESTAMP),
    ('c1b2a3d4-0000-4e00-9000-00000000000c', 'ws_three_good_things', 'Three good things', 'Teen achhi cheezein', 'Notice three things that went okay today.', false, 'worksheet', 'Notice three things that went okay today.', 'Aaj teen cheezein dekho jo theek se hui hain.', 'be_kinder', 'Positive psychology (savouring)', 'positive psychology practice of savouring; low effort and suitable for any day.', 'open', 'light', 3, $ws_ws_three_good_things${"version":1,"intro":"Our brains are good at remembering what went wrong. This is practice in noticing what went okay. Small and ordinary is perfect.","fields":[{"id":"one","type":"short_text","prompt":"What's one thing that went okay today?","required":true,"example":"The auto driver didn't argue about the fare."},{"id":"two","type":"short_text","prompt":"And another?","required":true},{"id":"three","type":"short_text","prompt":"And one more?","required":true},{"id":"my_part","type":"short_text","prompt":"Pick one. What part did you play in it, even a small one?"}],"closing":{"text":"Noticed and kept.","buttons":[{"label":"Save to my Treasure Box","action":"treasure_box"}]}}$ws_ws_three_good_things$::jsonb, $ws_ws_three_good_things${"version":1,"intro":"Dimaag ko yaad rehta hai ki kya galat hua. Ye practice hai dekhne ki kya theek hua. Chhoti aur aam cheezein bhi perfect hain.","fields":[{"id":"one","type":"short_text","prompt":"Aaj ek cheez kya theek hui?","required":true,"example":"Auto wale ne kiraye par baat nahi ki."},{"id":"two","type":"short_text","prompt":"Aur ek?","required":true},{"id":"three","type":"short_text","prompt":"Aur ek?","required":true},{"id":"my_part","type":"short_text","prompt":"Ek chuno. Isme aapka kya hissa tha, thoda sa bhi?"}],"closing":{"text":"Dekha aur sambhal ke rakha.","buttons":[{"label":"Mere Treasure Box mein save karo","action":"treasure_box"}]}}$ws_ws_three_good_things$::jsonb, 'approved', '2026-11-09'::timestamp, 20, NULL, CURRENT_TIMESTAMP),
    ('c1b2a3d4-0000-4e00-9000-00000000000d', 'ws_energy_audit', 'Energy audit', 'Energy audit', 'See what drains your energy and what fills it back up.', false, 'worksheet', 'See what drains your energy and what fills it back up.', 'Dekho aapki energy kya kha raha hai aur kya wapas bhar raha hai.', 'energy_life', 'Burnout self-monitoring', 'burnout self-monitoring of what drains and what restores energy, ending in one small adjustment.', 'open', 'light', 5, $ws_ws_energy_audit${"version":1,"intro":"Some things take more out of you than they give back. Others quietly fill you up. Let's look at your week.","fields":[{"id":"drains","type":"row_list","prompt":"What's been draining your energy this week?","example":"Back-to-back classes · Family WhatsApp group · Scrolling till 2 am.","columns":[{"id":"item","label":"Draining","type":"text"},{"id":"how_much","label":"How much?","type":"scale_0_10"}]},{"id":"gives","type":"row_list","prompt":"What's been giving you energy, even a little?","example":"Evening walk · Cooking with my roommate · Cricket on Sunday.","columns":[{"id":"item","label":"Giving energy","type":"text"},{"id":"how_much","label":"How much?","type":"scale_0_10"}]},{"id":"noticing","type":"long_text","prompt":"Looking at both lists, what do you notice?"},{"id":"one_change","type":"short_text","prompt":"Is there one drain you could shrink a little, or one source you could add a bit more of this week?","helper":"Tiny changes count. If nothing feels possible right now, that's useful to know too."}],"closing":{"text":"Knowing where your energy goes is the first step to protecting it."}}$ws_ws_energy_audit$::jsonb, $ws_ws_energy_audit${"version":1,"intro":"Kuch cheezein utna deti nahi jitna le leti hain. Kuch chup-chaap aapko bhar deti hain. Chalo aapka hafta dekhein.","fields":[{"id":"drains","type":"row_list","prompt":"Is hafte aapki energy kaunsi cheezein kha rahi hain?","example":"Lagaatar classes · Family WhatsApp group · Raat 2 baje tak scrolling.","columns":[{"id":"item","label":"Energy khaane wali","type":"text"},{"id":"how_much","label":"Kitna?","type":"scale_0_10"}]},{"id":"gives","type":"row_list","prompt":"Kaunsi cheezein aapko energy de rahi hain, thodi si bhi?","example":"Shaam ki walk · Roommate ke saath khana banana · Sunday ka cricket.","columns":[{"id":"item","label":"Energy dene wali","type":"text"},{"id":"how_much","label":"Kitna?","type":"scale_0_10"}]},{"id":"noticing","type":"long_text","prompt":"Dono list dekhkar kya notice karte ho?"},{"id":"one_change","type":"short_text","prompt":"Koi ek cheez jo energy kha rahi hai, use thoda kam kar sakte ho? Ya koi ek cheez jo energy deti hai, is hafte thodi zyada kar sakte ho?","helper":"Chhote badlav bhi count hote hain. Agar abhi kuch bhi possible na lage, toh woh bhi jaanna kaam ka hai."}],"closing":{"text":"Aapki energy kahan jaati hai, ye jaanna use bachane ka pehla kadam hai."}}$ws_ws_energy_audit$::jsonb, 'approved', '2026-11-09'::timestamp, 10, NULL, CURRENT_TIMESTAMP),
    ('c1b2a3d4-0000-4e00-9000-00000000000e', 'ws_bring_to_session', 'What I want to bring to session', 'Session mein kya le jaana chahta hoon', 'Jot down what you''d like to talk about next session.', false, 'worksheet', 'Jot down what you''d like to talk about next session.', 'Agle session mein kya baat karni hai, likh lo.', 'before_after', 'Client-led agenda setting', 'client-led agenda setting. If shared, it appears in session preparation.', 'open', 'light', 3, $ws_ws_bring_to_session${"version":1,"intro":"Sessions can go by fast, and things slip your mind. Jot down what you'd like to talk about, so it's ready when you need it.","fields":[{"id":"on_mind","type":"long_text","prompt":"What's been on your mind since last session?","required":true},{"id":"hard_to_say","type":"long_text","prompt":"Is there anything you've been finding hard to say out loud?","helper":"You can write it here first. You decide whether to share it."},{"id":"one_thing","type":"short_text","prompt":"If you could leave next session with one thing, what would it be?","example":"A plan for exam week · Just feeling heard."},{"id":"share_now","type":"choice","prompt":"Share with your therapist before the session?","options":[{"value":"share","label":"Share"},{"value":"private","label":"Keep private"}]}],"closing":{"text":"Ready when you are."}}$ws_ws_bring_to_session$::jsonb, $ws_ws_bring_to_session${"version":1,"intro":"Session jaldi nikal jaate hain, aur bahut baatein dimaag se nikal jaati hain. Jo kehna chahte ho woh likh lo, taaki waqt par taiyaar ho.","fields":[{"id":"on_mind","type":"long_text","prompt":"Pichhle session se ab tak kya cheez dimaag mein rahi?","required":true},{"id":"hard_to_say","type":"long_text","prompt":"Koi aisi baat hai jo bolne mein mushkil lag rahi hai?","helper":"Pehle yahan likh sakte ho. Share karna hai ya nahi, ye aap decide karte ho."},{"id":"one_thing","type":"short_text","prompt":"Agar agle session se ek cheez lekar jaana ho, woh kya hogi?","example":"Exam week ka plan · Bas suna hua mehsoos karna."},{"id":"share_now","type":"choice","prompt":"Session se pehle therapist ke saath share karna hai?","options":[{"value":"share","label":"Share karo"},{"value":"private","label":"Private rakho"}]}],"closing":{"text":"Jab aap taiyaar ho."}}$ws_ws_bring_to_session$::jsonb, 'approved', '2026-11-09'::timestamp, 10, NULL, CURRENT_TIMESTAMP),
    ('c1b2a3d4-0000-4e00-9000-00000000000f', 'ws_post_session', 'Post-session takeaway', 'Session ke baad takeaway', 'Catch what stood out from today''s session before it slips away.', false, 'worksheet', 'Catch what stood out from today''s session before it slips away.', 'Aaj ke session ki sabse badi baat sambhal lo, isse pehle ki woh bhool jaaye.', 'before_after', 'Between-session consolidation', 'holds on to learning between sessions; the main way insights from therapy reach the Treasure Box.', 'open', 'light', 3, $ws_ws_post_session${"version":1,"intro":"Right after a session is a good time to catch what stood out, before the day carries on.","fields":[{"id":"remember","type":"long_text","prompt":"What's one thing you want to remember from today?","required":true,"example":"Feeling anxious doesn't mean something bad is about to happen."},{"id":"want_to_try","type":"short_text","prompt":"Was there anything you'd like to try before next time?"},{"id":"didnt_sit_right","type":"short_text","prompt":"Anything that didn't sit right, or that you'd like to come back to?","helper":"It's okay to disagree with something from session. That's worth bringing up next time."},{"id":"save_it","type":"choice","prompt":"Save the first answer to your Treasure Box?","options":[{"value":"save","label":"Save it"},{"value":"not_now","label":"Not now"}]}],"closing":{"text":"Kept safe for whenever you need it."}}$ws_ws_post_session$::jsonb, $ws_ws_post_session${"version":1,"intro":"Session ke turant baad accha waqt hota hai ye dekhne ka ki kya baat alag laghi, isse pehle ki din aage badh jaaye.","fields":[{"id":"remember","type":"long_text","prompt":"Aaj se ek cheez kya yaad rakhna chahte ho?","required":true,"example":"Anxious lagne ka matlab ye nahi ki kuch bura hone wala hai."},{"id":"want_to_try","type":"short_text","prompt":"Koi cheez hai jo agle session se pehle try karna chahte ho?"},{"id":"didnt_sit_right","type":"short_text","prompt":"Koi baat jo theek nahi lagi, ya jispe wapas aana chahte ho?","helper":"Session ki kisi baat se sehmat na hona theek hai. Woh agli baar uthane layak hai."},{"id":"save_it","type":"choice","prompt":"Pehla jawab apne Treasure Box mein save karein?","options":[{"value":"save","label":"Save karo"},{"value":"not_now","label":"Abhi nahi"}]}],"closing":{"text":"Jab bhi zaroorat ho, sambhal ke rakha hai."}}$ws_ws_post_session$::jsonb, 'approved', '2026-11-09'::timestamp, 20, NULL, CURRENT_TIMESTAMP),
    ('c1b2a3d4-0000-4e00-9000-000000000010', 'ws_safety_plan', 'My plan for hard moments', 'Mushkil palon ka mera plan', 'The plan you made with your therapist for hard moments.', false, 'worksheet', 'The plan you made with your therapist for hard moments.', 'Mushkil palon ke liye woh plan jo aapne therapist ke saath banaya.', 'safety', 'Collaborative safety planning', 'follows the standard six-part structure of collaborative safety planning. Written in the client''s own words during session; only the therapist can edit it. Reachable in one tap from the crisis screen.', 'in_session', 'light', 15, $ws_ws_safety_plan${"version":1,"intro":"You made this with your therapist for times when things feel too much. It's here whenever you need it.","fields":[{"id":"signs","type":"row_list","prompt":"Signs a hard moment might be coming","therapistPrompt":"What thoughts, feelings, situations or behaviours tell you things are getting difficult?","columns":[{"id":"item","label":"Sign","type":"text"}]},{"id":"on_my_own","type":"row_list","prompt":"Things I can do on my own to get through it","therapistPrompt":"What helps you, even a little, when you're by yourself?","columns":[{"id":"item","label":"What helps","type":"text"}]},{"id":"people_places","type":"row_list","prompt":"People and places that help take my mind off it","therapistPrompt":"Who or where can you be around, without having to talk about how you feel?","columns":[{"id":"item","label":"Who or where","type":"text"}]},{"id":"ask_for_help","type":"row_list","prompt":"People I can ask for help","therapistPrompt":"Who could you tell that you're struggling?","columns":[{"id":"name","label":"Name","type":"text"},{"id":"phone","label":"Phone","type":"text"}]},{"id":"professional","type":"instruction","prompt":"Professional and crisis support"},{"id":"safer_surroundings","type":"row_list","prompt":"Making my surroundings safer","therapistPrompt":"What can you do to make your space safer during a hard moment?","columns":[{"id":"item","label":"What makes it safer","type":"text"}]},{"id":"one_reason","type":"short_text","prompt":"One reason that matters to me","therapistPrompt":"What's something worth holding on to?"}],"closing":{"buttons":[{"label":"Get help now","action":"get_help"}]}}$ws_ws_safety_plan$::jsonb, $ws_ws_safety_plan${"version":1,"intro":"Ye aapne apne therapist ke saath un waqton ke liye banaya hai jab sab kuch bahut zyada lagta hai. Jab zaroorat ho, ye yahan hai.","fields":[{"id":"signs","type":"row_list","prompt":"Mushkil waqt aane ke sanket","therapistPrompt":"Kaunsi soch, feeling, situation ya behaviour batati hai ki cheezein mushkil ho rahi hain?","columns":[{"id":"item","label":"Sanket","type":"text"}]},{"id":"on_my_own","type":"row_list","prompt":"Woh cheezein jo main akela kar sakta hoon","therapistPrompt":"Akele hone par kaunsi cheez madad karti hai, thodi si bhi?","columns":[{"id":"item","label":"Kya madad karta hai","type":"text"}]},{"id":"people_places","type":"row_list","prompt":"Log aur jagah jo dhyan hataane mein madad karte hain","therapistPrompt":"Kiske saath ya kahan reh sakte ho, bina ye batane ki ki aap kaisa feel kar rahe ho?","columns":[{"id":"item","label":"Kaun ya kahan","type":"text"}]},{"id":"ask_for_help","type":"row_list","prompt":"Log jinse main madad maang sakta hoon","therapistPrompt":"Kise bata sakte ho ki aap struggle kar rahe ho?","columns":[{"id":"name","label":"Naam","type":"text"},{"id":"phone","label":"Phone","type":"text"}]},{"id":"professional","type":"instruction","prompt":"Professional aur crisis support"},{"id":"safer_surroundings","type":"row_list","prompt":"Apne aas-paas ko safe banana","therapistPrompt":"Kya kar sakte ho jisse mushkil waqt mein aapki jagah zyada safe ho?","columns":[{"id":"item","label":"Kya safe banata hai","type":"text"}]},{"id":"one_reason","type":"short_text","prompt":"Ek wajah jo mere liye maayne rakhti hai","therapistPrompt":"Kaunsi cheez pakad ke rakhne layak hai?"}],"closing":{"buttons":[{"label":"Abhi madad lo","action":"get_help"}]}}$ws_ws_safety_plan$::jsonb, 'approved', '2026-11-09'::timestamp, 10, NULL, CURRENT_TIMESTAMP),
